<?php
/**
 * Studia360 - Administración de temas
 * Archivo: admin/contenidos/temas.php
 * Sin id_materia = todos los temas. Con id_materia = solo esa materia.
 */
declare(strict_types=1);
require_once __DIR__ . "/../../includes/seguridad.php";
exigirAdmin();
$temas=[]; $errores=[];
$nombreAdmin=trim(($_SESSION["nombres"]??"")." ".($_SESSION["apellidos"]??"")) ?: "Administrador";
function e($valor):string{return htmlspecialchars((string)$valor,ENT_QUOTES,"UTF-8");}
$idMateria=filter_var($_GET["id_materia"]??null,FILTER_VALIDATE_INT); if(!$idMateria||$idMateria<=0)$idMateria=null;
$materiaSeleccionada=null;
if($idMateria!==null){try{$stmt=$conexion->prepare("SELECT id_materia,nombre,descripcion FROM materias WHERE id_materia=? LIMIT 1");$stmt->execute([$idMateria]);$materiaSeleccionada=$stmt->fetch(PDO::FETCH_ASSOC);if(!$materiaSeleccionada){$errores[]="La materia seleccionada no existe.";$idMateria=null;}}catch(PDOException $e){$errores[]="No fue posible cargar la materia seleccionada.";$idMateria=null;}}
try{
$sql="SELECT t.id_tema,t.id_materia,t.nombre AS tema,t.descripcion,t.grado,t.contenido,m.nombre AS materia,m.descripcion AS descripcion_materia,(SELECT COUNT(*) FROM recursos r WHERE r.id_tema=t.id_tema AND r.estado='Activo') AS total_recursos,(SELECT COUNT(*) FROM evaluaciones ev WHERE ev.id_tema=t.id_tema) AS total_evaluaciones,(SELECT ct.estado FROM contenido_temas ct WHERE ct.id_tema=t.id_tema ORDER BY CASE WHEN ct.estado='Publicado' THEN 1 WHEN ct.estado='Borrador' THEN 2 ELSE 3 END,ct.fecha_actualizacion DESC,ct.id_contenido DESC LIMIT 1) AS estado_contenido FROM temas t INNER JOIN materias m ON m.id_materia=t.id_materia WHERE t.grado IN ('9','10','11')";
$params=[]; if($idMateria!==null){$sql.=" AND t.id_materia=?";$params[]=$idMateria;} $sql.=" ORDER BY CAST(t.grado AS UNSIGNED) ASC,m.nombre ASC,t.nombre ASC";
$stmt=$conexion->prepare($sql);$stmt->execute($params);$temas=$stmt->fetchAll(PDO::FETCH_ASSOC);
}catch(PDOException $e){$errores[]="No fue posible cargar los temas.";}
$totalTemas=count($temas);$total9=$total10=$total11=0;foreach($temas as $t){if((string)$t["grado"]==='9')$total9++;elseif((string)$t["grado"]==='10')$total10++;elseif((string)$t["grado"]==='11')$total11++;}
$urlDashboard=urlAplicacion("/admin/dashboard.php");$urlMaterias=urlAplicacion("/admin/contenidos/materias.php");$urlNuevoTema=urlAplicacion("/admin/contenidos/nuevo_tema.php");$urlCerrarSesion=urlAplicacion("/cerrar_sesion.php");
$grados=["9"=>["nombre"=>"Noveno","icono"=>"bi-1-circle-fill"],"10"=>["nombre"=>"Décimo","icono"=>"bi-2-circle-fill"],"11"=>["nombre"=>"Undécimo","icono"=>"bi-3-circle-fill"]];
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title><?= $materiaSeleccionada?"Temas de ".e($materiaSeleccionada["nombre"]):"Todos los temas"?> | Studia360</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">
<style>
:root{--blue:#0d6efd;--dark:#20252b;--bg:#f4f7fb;--border:#e2e8f0;--muted:#64748b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#172033;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.navbar-studia{background:var(--dark);min-height:58px;box-shadow:0 3px 14px rgba(15,23,42,.12)}.brand{font-weight:800}.page{width:min(1220px,calc(100% - 32px));margin:30px auto 60px}.hero{background:linear-gradient(135deg,#0d6efd,#084298);color:#fff;border-radius:22px;padding:28px 30px;margin-bottom:20px;box-shadow:0 15px 34px rgba(13,110,253,.15)}.kicker{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78}.hero h1{font-size:clamp(2rem,4vw,3rem);font-weight:850;letter-spacing:-.04em;margin:5px 0}.hero p{max-width:780px;margin:0;opacity:.82;line-height:1.6}.actions{display:flex;gap:9px;flex-wrap:wrap}.actions .btn{border-radius:11px;font-weight:700}.context,.filter{background:#fff;border:1px solid var(--border);border-radius:18px;padding:18px 20px;margin-bottom:18px;box-shadow:0 7px 22px rgba(15,23,42,.045)}.context{display:flex;align-items:center;justify-content:space-between;gap:16px}.context-icon{width:48px;height:48px;border-radius:14px;background:#edf4ff;color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:1.35rem}.filter-title{font-weight:800}.filter-sub{color:var(--muted);font-size:.85rem;margin:3px 0 14px}.grades{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.grade{border:1px solid #d9e2ef;background:#fff;color:#334155;border-radius:13px;min-height:62px;padding:9px 12px;display:flex;align-items:center;justify-content:center;gap:8px;font-weight:750;cursor:pointer;transition:.18s}.grade:hover{border-color:#9dbcf1;transform:translateY(-1px)}.grade.active{background:var(--blue);color:#fff;border-color:var(--blue);box-shadow:0 7px 17px rgba(13,110,253,.22)}.count{background:#eef4fb;color:#475569;padding:3px 8px;border-radius:999px;font-size:.72rem}.grade.active .count{background:rgba(255,255,255,.18);color:#fff}.results{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.results strong{color:var(--blue)}.muted{color:var(--muted);font-size:.86rem}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.card-topic{background:#fff;border:1px solid var(--border);border-radius:17px;padding:18px;min-height:330px;display:flex;flex-direction:column;box-shadow:0 6px 20px rgba(15,23,42,.045);transition:.18s}.card-topic:hover{transform:translateY(-3px);box-shadow:0 12px 27px rgba(15,23,42,.09)}.card-topic.hidden{display:none}.top{display:flex;gap:12px;align-items:flex-start;margin-bottom:13px}.topic-icon{width:45px;height:45px;border-radius:13px;background:#edf4ff;color:var(--blue);display:flex;align-items:center;justify-content:center;flex-shrink:0}.grade-label{display:inline-flex;align-items:center;gap:5px;padding:4px 8px;border-radius:7px;background:#eff6ff;color:var(--blue);font-size:.7rem;font-weight:800;margin-bottom:7px}.topic-name{font-size:1.04rem;font-weight:850;line-height:1.28;margin:0}.subject{color:var(--muted);font-size:.8rem;margin-top:5px}.desc{color:#64748b;line-height:1.55;font-size:.9rem;margin-bottom:14px}.meta{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:14px}.meta span{background:#f8fafc;border:1px solid #e5eaf1;color:#64748b;border-radius:8px;padding:5px 8px;font-size:.72rem}.status{display:inline-flex;align-items:center;gap:6px;width:max-content;border-radius:999px;padding:5px 9px;font-size:.72rem;font-weight:800;margin-bottom:15px}.published{background:#e8f7ef;color:#147a45}.draft{background:#fff6dc;color:#996c00}.empty-status{background:#f1f5f9;color:#64748b}.topic-actions{margin-top:auto;display:grid;gap:7px}.topic-actions .btn{border-radius:9px;font-size:.82rem;font-weight:650}.manage{background:var(--blue);border-color:var(--blue);color:#fff}.manage:hover{background:#0b5ed7;color:#fff}.empty{display:none;background:#fff;border:1px dashed #cbd5e1;border-radius:18px;text-align:center;padding:45px 20px}.empty.show{display:block}.empty-icon{width:60px;height:60px;border-radius:18px;background:#edf4ff;color:var(--blue);display:flex;align-items:center;justify-content:center;margin:0 auto 14px;font-size:1.6rem}@media(max-width:980px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.page{width:calc(100% - 20px);margin-top:15px}.hero{padding:23px;border-radius:18px}.context{align-items:flex-start;flex-direction:column}.context .btn{width:100%}.grid{grid-template-columns:1fr}.grades{grid-template-columns:1fr 1fr}.results{align-items:flex-start;flex-direction:column;gap:5px}}
</style></head><body>
<nav class="navbar navbar-dark navbar-studia"><div class="container-fluid px-3 px-md-4"><a href="<?=e($urlDashboard)?>" class="navbar-brand brand"><i class="bi bi-mortarboard-fill me-2"></i>Studia360</a><div class="d-flex align-items-center gap-2"><span class="text-white small d-none d-md-inline"><i class="bi bi-shield-check me-1"></i><?=e($nombreAdmin)?></span><a href="<?=e($urlCerrarSesion)?>" class="btn btn-outline-light btn-sm"><i class="bi bi-box-arrow-right me-1"></i>Cerrar sesión</a></div></div></nav>
<main class="page"><header class="hero"><div class="d-flex justify-content-between align-items-center flex-wrap gap-4"><div><div class="kicker">Administración de contenidos</div><h1><?= $materiaSeleccionada?"Temas de ".e($materiaSeleccionada["nombre"]):"Todos los temas"?></h1><p><?= $materiaSeleccionada?"Estás administrando únicamente los temas de esta materia. Puedes organizarlos por grado.":"Consulta y administra todos los temas de Studia360. Puedes filtrar instantáneamente por grado sin recargar la página."?></p></div><div class="actions"><a href="<?=e($urlMaterias)?>" class="btn btn-light"><i class="bi bi-book me-1"></i>Materias</a><a href="<?=e($urlNuevoTema)?>" class="btn btn-light"><i class="bi bi-plus-lg me-1"></i>Nuevo tema</a></div></div></header>
<?php foreach($errores as $er):?><div class="alert alert-danger border-0 shadow-sm mb-3"><i class="bi bi-exclamation-triangle-fill me-2"></i><?=e($er)?></div><?php endforeach;?>
<?php if($materiaSeleccionada):?><div class="context"><div class="d-flex align-items-center gap-3"><div class="context-icon"><i class="bi bi-book-fill"></i></div><div><div class="fw-bold"><?=e($materiaSeleccionada["nombre"])?></div><div class="muted"><?=e($materiaSeleccionada["descripcion"]?:"Sin descripción de la materia.")?></div></div></div><a href="<?=e($urlMaterias)?>" class="btn btn-outline-primary"><i class="bi bi-arrow-left me-1"></i>Cambiar materia</a></div><?php endif;?>
<section class="filter"><div class="filter-title"><i class="bi bi-funnel-fill text-primary me-1"></i>Filtrar por grado</div><div class="filter-sub">La selección se aplica automáticamente y no recarga la página.</div><div class="grades"><button type="button" class="grade active" data-grade="all"><i class="bi bi-grid-3x3-gap-fill"></i>Todos <span class="count"><?=$totalTemas?></span></button><button type="button" class="grade" data-grade="9"><i class="bi bi-1-circle-fill"></i>9° <span class="count"><?=$total9?></span></button><button type="button" class="grade" data-grade="10"><i class="bi bi-2-circle-fill"></i>10° <span class="count"><?=$total10?></span></button><button type="button" class="grade" data-grade="11"><i class="bi bi-3-circle-fill"></i>11° <span class="count"><?=$total11?></span></button></div></section>
<div class="results"><div>Mostrando <strong id="visibleCount"><?=$totalTemas?></strong> tema(s)</div><div class="muted" id="activeFilterText">Todos los grados</div></div>
<section class="grid" id="topicsGrid">
<?php foreach($temas as $t): $g=(string)$t["grado"]; $estado=trim((string)($t["estado_contenido"]??"")); if($estado===""&&trim((string)($t["contenido"]??""))!=="")$estado="Publicado"; $gn=$grados[$g]["nombre"]??"Grado";$gi=$grados[$g]["icono"]??"bi-mortarboard"; ?>
<article class="card-topic" data-grade="<?=e($g)?>"><div class="top"><div class="topic-icon"><i class="bi bi-journal-text"></i></div><div class="flex-grow-1"><div class="grade-label"><i class="bi <?=e($gi)?>"></i><?=e($gn)?> (<?=e($g)?>°)</div><h2 class="topic-name"><?=e($t["tema"])?></h2><?php if(!$materiaSeleccionada):?><div class="subject"><i class="bi bi-book me-1"></i><?=e($t["materia"])?></div><?php endif;?></div></div><p class="desc"><?=e($t["descripcion"]?:"Este tema todavía no tiene una descripción.")?></p><div class="meta"><span><i class="bi bi-paperclip me-1"></i><?= (int)$t["total_recursos"]?> recurso(s)</span><span><i class="bi bi-clipboard-check me-1"></i><?= (int)$t["total_evaluaciones"]?> evaluación(es)</span></div><?php if($estado==="Publicado"):?><div class="status published"><i class="bi bi-check-circle-fill"></i>Contenido publicado</div><?php elseif($estado==="Borrador"):?><div class="status draft"><i class="bi bi-pencil-square"></i>Borrador guardado</div><?php else:?><div class="status empty-status"><i class="bi bi-file-earmark"></i>Sin contenido</div><?php endif;?><div class="topic-actions"><a href="editar_tema.php?id=<?=(int)$t["id_tema"]?>" class="btn manage"><i class="bi bi-pencil-square me-1"></i>Administrar contenido</a><a href="informacion_tema.php?id=<?=(int)$t["id_tema"]?>" class="btn btn-outline-secondary"><i class="bi bi-gear me-1"></i>Información del tema</a><a href="<?=e(urlAplicacion("/estudiante/tema.php?id=".(int)$t["id_tema"]))?>" target="_blank" class="btn btn-outline-primary"><i class="bi bi-eye me-1"></i>Vista previa</a><a href="eliminar_tema.php?id=<?=(int)$t["id_tema"]?>" class="btn btn-outline-danger" onclick="return confirm('¿Seguro que deseas eliminar este tema? Esta acción puede afectar su contenido, recursos y evaluaciones relacionadas.');"><i class="bi bi-trash3 me-1"></i>Eliminar tema</a></div></article>
<?php endforeach;?></section>
<div class="empty" id="emptyState"><div class="empty-icon"><i class="bi bi-journal-x"></i></div><h3 class="h5 fw-bold">No hay temas para este filtro</h3><p class="text-secondary mb-0">No existen temas del grado seleccionado <?= $materiaSeleccionada?"dentro de esta materia.":"en Studia360."?></p></div></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const fs=document.querySelectorAll('.grade'),cards=document.querySelectorAll('.card-topic'),count=document.getElementById('visibleCount'),text=document.getElementById('activeFilterText'),empty=document.getElementById('emptyState');const names={all:'Todos los grados',9:'Noveno (9°)',10:'Décimo (10°)',11:'Undécimo (11°)'};function apply(g){let n=0;cards.forEach(c=>{const show=g==='all'||c.dataset.grade===g;c.classList.toggle('hidden',!show);if(show)n++;});count.textContent=n;text.textContent=names[g]||names.all;empty.classList.toggle('show',n===0)}fs.forEach(f=>f.addEventListener('click',()=>{fs.forEach(x=>x.classList.remove('active'));f.classList.add('active');apply(f.dataset.grade)}));apply('all')});</script></body></html>
